# Mark seeds
for (r, c) in ones_test:
    grid[r][c] = 1
for (r, c) in sixes_test:
    grid[r][c] = 6

def has_block(r0, c0, dr, dc):
    """Find if colored cell exists in direction (dr, dc). Returns (block_r, block_c, k) or None."""
    k = 1
    while k < 100:
        r, c = r0 + dr*k, c0 + dc*k
        if 0 <= r < H and 0 <= c < W:
            if grid[r][c] in (1, 6):
                return (r, c, k)
        else:
            return None
        k += 1
    return None

# Step 1: 6s extend up-left and down-right
for (r0, c0) in sixes_test:
    # up-left
    for k in range(1, 100):
        r, c = r0 - k, c0 - k
        if 0 <= r < H and 0 <= c < W:
            if grid[r][c] in (1, 6):
                break
            grid[r][c] = 6
        else:
            break

    # down-right
    for k in range(1, 100):
        r, c = r0 + k, c0 + k
        if 0 <= r < H and 0 <= c < W:
            if grid[r][c] in (1, 6):
                break
            grid[r][c] = 6
        else:
            break

# Step 2: 1s extend up-right and down-left, but only fill if blocked
for (r0, c0) in ones_test:
    # up-right (r--, c++)
    block = has_block(r0, c0, -1, 1)
    if block is not None:
        br, bc, bk = block
        for k in range(1, bk):
            r, c = r0 - k, c0 + k
            if 0 <= r < H and 0 <= c < W and grid[r][c] == bg:
